"use strict";(globalThis.webpackChunk_8x8_developer_docs=globalThis.webpackChunk_8x8_developer_docs||[]).push([[34733],{88681:e=>{e.exports=JSON.parse('{"id":"2026-11-20-whatsapp-ctwa-referral-inbound-webhook","date":"2026-11-20","products":["Connect"],"product":"Connect","channel":"WhatsApp","changeType":"Added","title":"Click-to-WhatsApp ad details in the inbound Messaging Apps webhook","excerpt":"The inbound Messaging Apps webhook(/connect/docs/inbound-chatapps-message) now tells you when a WhatsApp conversation started from a Click-to-WhatsApp ad or a Facebook or Instagram post.","hasArticle":true,"bodyHtml":"<p>The <a href=\\"/connect/docs/inbound-chatapps-message\\">inbound Messaging Apps webhook</a> now tells you when a WhatsApp conversation started from a Click-to-WhatsApp ad or a Facebook or Instagram post.</p>\\n<p>The message a user sends right after tapping the ad includes a new optional <code>referral</code> object with the details WhatsApp sends about the ad: <code>sourceType</code>, <code>sourceId</code>, <code>sourceUrl</code>, <code>headline</code>, <code>body</code>, <code>mediaType</code>, <code>imageUrl</code>, <code>videoUrl</code>, <code>thumbnailUrl</code>, <code>ctwaClid</code> and <code>welcomeMessage</code>. Store it when it arrives if you want to tag the whole conversation as an ad lead or attribute it to a campaign.</p>\\n<p>The field is available in webhook formats v2 and v3. Messages that do not come from an ad are unchanged: the <code>referral</code> key is left out.</p>\\n"}')}}]);